const dt=x=>x?new Date(x).toLocaleString('pl-PL'):'—'
function Button({children,onPress,primary=false,danger=false,disabled=false,small=false}){return <Pressable disabled={disabled} onPress={onPress} style={[s.btn,small&&s.btnSmall,primary&&s.btnPrimary,danger&&s.btnDanger,disabled&&{opacity:.45}]}><Text style={[s.btnTxt,primary&&{color:'#111'}]}>{children}</Text></Pressable>}
function Card({title,value,sub}){return <View style={s.card}><Text style={s.cardTitle}>{title}</Text><Text style={s.cardValue}>{value}</Text><Text style={s.muted}>{sub}</Text></View>}
function Section({title,children,action}){return <View style={s.panel}><View style={s.panelHead}><Text style={s.panelTitle}>{title}</Text>{action}</View>{children}</View>}
let activeVoiceOwner=null
function VoiceField({label,value,onChangeText,placeholder,disabled=false}){const owner=useRef(Symbol(label)),base=useRef(''),[listening,setListening]=useState(false),[error,setError]=useState('');useSpeechRecognitionEvent('start',()=>{if(activeVoiceOwner===owner.current)setListening(true)});useSpeechRecognitionEvent('end',()=>{if(activeVoiceOwner===owner.current){setListening(false);activeVoiceOwner=null}});useSpeechRecognitionEvent('result',event=>{if(activeVoiceOwner!==owner.current)return;const transcript=event.results?.[0]?.transcript||'';if(transcript)onChangeText(joinVoiceText(base.current,transcript))});useSpeechRecognitionEvent('error',event=>{if(activeVoiceOwner!==owner.current)return;setListening(false);setError(voiceErrorMessage(event.error));activeVoiceOwner=null});useEffect(()=>()=>{if(activeVoiceOwner===owner.current){ExpoSpeechRecognitionModule.abort();activeVoiceOwner=null}},[]);const toggle=async()=>{if(listening){ExpoSpeechRecognitionModule.stop();return}setError('');if(activeVoiceOwner)ExpoSpeechRecognitionModule.abort();const permission=await ExpoSpeechRecognitionModule.requestPermissionsAsync();if(!permission.granted){setError('Brak dostępu do mikrofonu.');return}if(!ExpoSpeechRecognitionModule.isRecognitionAvailable()){setError('Włącz usługę rozpoznawania mowy w ustawieniach Androida.');return}base.current=String(value||'');activeVoiceOwner=owner.current;ExpoSpeechRecognitionModule.start({lang:'pl-PL',interimResults:true,continuous:false,maxAlternatives:1})};return <View style={s.field}><Text style={s.label}>{label}</Text><View style={[ve.wrap,listening&&ve.wrapActive]}><TextInput editable={!disabled} style={[s.input,s.area,ve.input,disabled&&{opacity:.5}]} value={String(value??'')} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#65717c" multiline/><Pressable disabled={disabled} onPress={toggle} style={[ve.button,listening&&ve.buttonActive]}><Text style={ve.icon}>🎙</Text><Text style={ve.buttonText}>{listening?'SŁUCHAM':'DYKTUJ'}</Text></Pressable></View>{listening&&<Text style={ve.status}>● Mów po polsku. Zatrzymaj po zakończeniu.</Text>}{!!error&&<Text style={ve.error}>{error}</Text>}</View>}
function Field({label,value,onChangeText,placeholder,multiline=false,keyboardType,disabled=false,voice=false}){if(multiline&&voice)return <VoiceField label={label} value={value} onChangeText={onChangeText} placeholder={placeholder} disabled={disabled}/>;return <View style={s.field}><Text style={s.label}>{label}</Text><TextInput editable={!disabled} style={[s.input,multiline&&s.area,disabled&&{opacity:.5}]} value={String(value??'')} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#65717c" multiline={multiline} keyboardType={keyboardType}/></View>}
function SelectField({label,value,items,onChange,placeholder='— wybierz —',disabled=false,manualLabel='Inny / wpisz ręcznie…'}){const[open,setOpen]=useState(false);return <View style={s.field}><Text style={s.label}>{label}</Text><Pressable disabled={disabled} onPress={()=>setOpen(true)} style={[s.input,s.selectBox,disabled&&{opacity:.5}]}><Text style={[s.selectText,!value&&{color:'#65717c'}]}>{value||placeholder}</Text><Text style={s.selectArrow}>▾</Text></Pressable><Modal visible={open} transparent animationType="fade" onRequestClose={()=>setOpen(false)}><Pressable style={s.modalShade} onPress={()=>setOpen(false)}><Pressable style={s.selectModal} onPress={()=>{}}><Text style={[s.panelTitle,{marginBottom:12}]}>{label}</Text><ScrollView style={{maxHeight:480,borderWidth:1,borderColor:'#2a342c',borderRadius:10,backgroundColor:'#111512'}}>{items.map(x=><Pressable key={String(x)} style={s.selectItem} onPress={()=>{onChange(String(x));setOpen(false)}}><Text style={s.rowTitle}>{String(x)}</Text></Pressable>)}<Pressable style={s.selectItem} onPress={()=>{onChange('__manual__');setOpen(false)}}><Text style={s.warn}>{manualLabel}</Text></Pressable></ScrollView><Button onPress={()=>setOpen(false)}>Anuluj</Button></Pressable></Pressable></Modal></View>}
function PillRow({items,value,onChange}){return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.pills}>{items.map(x=><Pressable key={x} onPress={()=>onChange(x)} style={[s.pill,value===x&&s.pillOn]}><Text style={[s.pillText,value===x&&{color:'#111'}]}>{String(x).replaceAll('_',' ')}</Text></Pressable>)}</ScrollView>}
function Status({value,onChange}){return <PillRow items={statuses} value={value} onChange={onChange}/>}
function BootScreen(){const reveal=useRef(new Animated.Value(0)).current,pulse=useRef(new Animated.Value(0)).current;useEffect(()=>{Animated.parallel([Animated.timing(reveal,{toValue:1,duration:650,easing:Easing.out(Easing.cubic),useNativeDriver:true}),Animated.loop(Animated.sequence([Animated.timing(pulse,{toValue:1,duration:900,easing:Easing.inOut(Easing.quad),useNativeDriver:true}),Animated.timing(pulse,{toValue:0,duration:900,easing:Easing.inOut(Easing.quad),useNativeDriver:true})]))]).start()},[pulse,reveal]);return <SafeAreaView style={s.bootRoot}><Animated.View style={{opacity:reveal,transform:[{translateY:reveal.interpolate({inputRange:[0,1],outputRange:[12,0]})},{scale:pulse.interpolate({inputRange:[0,1],outputRange:[1,1.018]})}]}}><Image source={BRAND_LOGO} resizeMode="contain" style={s.bootLogo}/></Animated.View><View style={s.bootLoader}><ActivityIndicator color="#b9ef79" size="small"/><Text style={s.bootText}>URUCHAMIANIE SYSTEMU WARSZTATOWEGO</Text></View></SafeAreaView>}

export default function App(){
 const{width}=useWindowDimensions(); const compact=width<900
 const[ready,setReady]=useState(false),[page,setPage]=useState('dashboard'),[tick,setTick]=useState(0),[syncing,setSyncing]=useState(false),[lastSync,setLastSync]=useState(''),[selectedOrder,setSelectedOrder]=useState('')
 useEffect(()=>{Promise.all([initDb(),new Promise(resolve=>setTimeout(resolve,900))]).then(()=>setReady(true)).catch(e=>Alert.alert('Baza',e.message))},[])
 const refresh=()=>setTick(x=>x+1)
 const sync=async(silent=false,full=false)=>{setSyncing(true);try{const r=await syncNow({full});setLastSync(new Date().toLocaleTimeString('pl-PL'));refresh();if(!silent){const emptyHint=r.full&&r.remoteRows===0?'\n\nChmura tego konta jest pusta. Sprawd\u017a, czy na obu urz\u0105dzeniach zalogowano ten sam adres e-mail.':'';Alert.alert('Synchronizacja',`Tryb: ${r.full?'pe\u0142na':'szybka'}\nWys\u0142ano rekord\u00f3w: ${r.pushed}\nPobrano rekord\u00f3w: ${r.pulled}\nRozstrzygni\u0119to konflikt\u00f3w na korzy\u015b\u0107 nowszych danych: ${r.conflicts||0}\nPomini\u0119to lokalnych zmian: ${r.skipped||0}\nZdj\u0119cia \u2191 ${r.filesUp||0} / \u2193 ${r.filesDown||0}${emptyHint}`)}}catch(e){if(!silent)Alert.alert('B\u0142\u0105d synchronizacji',e.message)}finally{setSyncing(false)}}
 useEffect(()=>{if(!ready)return;let alive=true;const boot=async()=>{const c=await loadCloud();if(c.autoSync&&alive)sync(true)};boot();const t=setInterval(async()=>{const c=await loadCloud();if(c.autoSync&&!syncing)sync(true)},30000);return()=>{alive=false;clearInterval(t)}},[ready])
 const openCenter=id=>{setSelectedOrder(id);setPage('orderCenter')}
 if(!ready)return <BootScreen/>
 return <SafeAreaView style={s.root}><View style={s.shell}>{!compact&&<Sidebar page={page} setPage={setPage} sync={sync} syncing={syncing} lastSync={lastSync}/>}<View style={s.main}><Header page={page} compact={compact} sync={sync} syncing={syncing}/><ScrollView horizontal={compact} contentContainerStyle={compact?s.compactOuter:undefined}><ScrollView contentContainerStyle={[s.content,compact&&s.contentCompact]}>{compact&&<MobileNav page={page} setPage={setPage}/>}{page==='dashboard'&&<WorkshopDashboard tick={tick} openCenter={openCenter} navigate={setPage}/>}{page==='intake'&&<Intake refresh={refresh} openCenter={openCenter}/>}{page==='workflow'&&<Workflow tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='schedule'&&<Schedule tick={tick} refresh={refresh}/>}{page==='orders'&&<Orders tick={tick} refresh={refresh} openCenter={openCenter}/>}{page==='orderCenter'&&<OrderCenter tick={tick} refresh={refresh} orderId={selectedOrder} setOrderId={setSelectedOrder}/>}{page==='customers'&&<RecordsList tick={tick} type="customers" title="Klienci" refresh={refresh} render={p=><><Text style={s.rowTitle}>{p.name}</Text><Text style={s.muted}>{p.phone||'brak telefonu'} · {p.email||'brak e-mail'}</Text></>}/>}{page==='vehicles'&&<RecordsList tick={tick} type="vehicles" title="Pojazdy" refresh={refresh} render={p=><><Text style={s.rowTitle}>{p.plate||'bez rej.'} · {p.make||''} {p.model||''}</Text><Text style={s.muted}>{[p.generation,p.year,p.engine,p.power_hp?`${p.power_hp} KM`:'',p.engine_code].filter(Boolean).join(' · ')||'brak danych wersji'} · VIN {p.vin||'—'} · {p.mileage||0} km</Text></>}/>}{page==='parts'&&<Parts tick={tick} refresh={refresh}/>}{page==='diagnostics'&&<Diagnostics tick={tick} refresh={refresh}/>}{page==='payments'&&<Payments tick={tick} refresh={refresh}/>}{page==='finance'&&<MobileFinance tick={tick} openCenter={openCenter}/>}{page==='documents'&&<Documents/>}{page==='settings'&&<Settings sync={sync} syncing={syncing}/>}</ScrollView></ScrollView></View></View></SafeAreaView>
}
function Sidebar({page,setPage,sync,syncing,lastSync}){return <View style={s.sidebar}><View style={s.brand}><Image source={BRAND_LOGO} resizeMode="contain" style={s.sidebarLogo}/><Text style={s.brandS}>ANDROID OS 0.16.0</Text></View><ScrollView>{NAV.map(([id,label])=><Pressable key={id} style={[s.nav,page===id&&s.navOn]} onPress={()=>setPage(id)}><Text style={[s.navTxt,page===id&&{color:'#cbe4ad'}]}>{label}</Text></Pressable>)}</ScrollView><View style={s.syncBox}><Text style={s.muted}>OFFLINE-FIRST</Text><Button onPress={()=>sync(false)} disabled={syncing}>{syncing?'Synchronizuję…':'↻ Synchronizuj'}</Button>{!!lastSync&&<Text style={s.muted}>ostatnio {lastSync}</Text>}</View></View>}
function MobileNav({page,setPage}){return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.mobileNav}>{NAV.map(([id,label])=><Pressable key={id} onPress={()=>setPage(id)} style={[s.pill,page===id&&s.pillOn]}><Text style={[s.pillText,page===id&&{color:'#111'}]}>{label}</Text></Pressable>)}</ScrollView>}
function Header({page,compact,sync,syncing}){const n=Object.fromEntries(NAV);return <View style={s.header}><View><Text style={s.eyebrow}>AUTOLOGIKA / {page.toUpperCase()}</Text><Text style={s.h1}>{n[page]}</Text></View><View style={s.headerRight}><View style={s.local}><View style={s.dot}/><Text style={s.localT}>BAZA LOKALNA</Text></View>{compact&&<Button small onPress={()=>sync(false)} disabled={syncing}>↻</Button>}</View></View>}
function Dashboard({tick,openCenter}){const[c,setC]=useState([]),[v,setV]=useState([]),[o,setO]=useState([]),[p,setP]=useState([]);useEffect(()=>{Promise.all([list('customers'),list('vehicles'),list('orders'),list('payments')]).then(([a,b,d,e])=>{setC(a);setV(b);setO(d);setP(e)})},[tick]);const active=o.filter(x=>x.payload.status!=='WYDANE'),attention=active.filter(x=>x.payload.wait_state&&x.payload.wait_state!=='BRAK'),paid=p.reduce((a,x)=>a+Number(x.payload.amount||0),0);return <><View style={s.cards}><Card title="Otwarte zlecenia" value={active.length} sub="aktywnych aut"/><Card title="Do uwagi" value={attention.length} sub="oczekuje / blokada"/><Card title="Płatności" value={money(paid)} sub="w zsynchronizowanych wpisach"/><Card title="Klienci" value={c.length} sub={`${v.length} pojazdów`}/></View><Section title="Aktywne zlecenia">{active.slice(0,10).map(x=><Pressable onPress={()=>openCenter(x.cloud_id)} style={s.row} key={x.cloud_id}><View style={{flex:1}}><Text style={s.rowTitle}>{x.payload.plate||'bez rej.'} · {x.payload.title||'Zlecenie'}</Text><Text style={s.muted}>{x.payload.customer||''} · {x.payload.make||''} {x.payload.model||''}</Text></View><View style={{alignItems:'flex-end'}}><Text style={s.badge}>{x.payload.status||'PRZYJETE'}</Text>{Boolean(x.payload.wait_state)&&x.payload.wait_state!=='BRAK'?<Text style={s.warn}>CZEKA: {x.payload.wait_state}</Text>:null}</View></Pressable>)}{!active.length&&<Text style={s.muted}>Brak aktywnych zleceń.</Text>}</Section></>}
function Intake({refresh,openCenter}){
 const blank={name:'',phone:'',plate:'',vin:'',make:'',model:'',generation:'',year:'',engine:'',power_hp:'',engine_code:'',mileage:'',title:'',complaint:'',intake_notes:''}
 const[d,setD]=useState(blank),[scan,setScan]=useState(false)
 const[manual,setManual]=useState({make:false,model:false,generation:false,year:false,engine:false,power:false,code:false})
 const models=vehicleModels(d.make),generations=vehicleGenerations(d.make,d.model),hasDetails=generations.length>0
 const years=hasDetails&&d.generation?generationYears(d.make,d.model,d.generation):vehicleYears(d.make,d.model)
 const engines=hasDetails&&d.generation?generationEngineNames(d.make,d.model,d.generation):vehicleEngines(d.make,d.model)
 const powers=hasDetails&&d.generation&&d.engine?enginePowers(d.make,d.model,d.generation,d.engine):[]
 const codes=hasDetails&&d.generation&&d.engine?engineCodes(d.make,d.model,d.generation,d.engine,d.power_hp):[]
 const choose=(field,value)=>{
   if(value==='__manual__')return setManual(m=>({...m,[field]:true,...(field==='make'?{model:true,generation:true,engine:true,power:true,code:true}:{}),...(field==='model'?{generation:true,engine:true,power:true,code:true}:{}),...(field==='generation'?{engine:true,power:true,code:true}:{}),...(field==='engine'?{power:true,code:true}:{}),...(field==='power'?{code:true}:{})}))
   const reset={}
   if(field==='make')Object.assign(reset,{model:'',generation:'',year:'',engine:'',power_hp:'',engine_code:''})
   if(field==='model')Object.assign(reset,{generation:'',year:'',engine:'',power_hp:'',engine_code:''})
   if(field==='generation')Object.assign(reset,{year:'',engine:'',power_hp:'',engine_code:''})
   if(field==='year'){}
   if(field==='engine')Object.assign(reset,{power_hp:'',engine_code:''})
   if(field==='power')Object.assign(reset,{engine_code:''})
   const key=field==='power'?'power_hp':field==='code'?'engine_code':field
   setManual(m=>({...m,[field]:false,...(field==='make'?{model:false,generation:false,year:false,engine:false,power:false,code:false}:{}),...(field==='model'?{generation:false,year:false,engine:false,power:false,code:false}:{}),...(field==='generation'?{year:false,engine:false,power:false,code:false}:{}),...(field==='engine'?{power:false,code:false}:{}),...(field==='power'?{code:false}:{})}))
   setD(x=>({...x,...reset,[key]:value}))
 }
 const save=async()=>{if(!d.name||!d.title)return Alert.alert('Brak danych','Podaj klienta i temat zlecenia.');const c=uid(),v=uid(),o=uid();const vehicle={customer_cloud_id:c,plate:d.plate.toUpperCase(),vin:d.vin.toUpperCase(),make:d.make,model:d.model,generation:d.generation,year:Number(d.year)||null,engine:d.engine,power_hp:Number(d.power_hp)||null,engine_code:d.engine_code.toUpperCase(),mileage:Number(d.mileage)||0};await put('customers',c,{name:d.name,phone:d.phone,email:'',company:'',notes:''});await put('vehicles',v,vehicle);await put('orders',o,{vehicle_cloud_id:v,title:d.title,complaint:d.complaint,status:'PRZYJETE',priority:'NORMALNY',wait_state:'BRAK',plate:vehicle.plate,make:d.make,model:d.model,generation:d.generation,year:vehicle.year,engine:d.engine,power_hp:vehicle.power_hp,engine_code:vehicle.engine_code,customer:d.name,total:0});await put('order_notes',uid(),{order_cloud_id:o,intake_notes:d.intake_notes||'',qc_notes:'',release_notes:''});setD(blank);setManual({make:false,model:false,generation:false,year:false,engine:false,power:false,code:false});refresh();Alert.alert('Autologika','Zlecenie zapisane lokalnie.',[{text:'OK'},{text:'Otwórz zlecenie',onPress:()=>openCenter(o)}])}
 return <Section title="Szybkie przyjęcie"><Text style={s.eyebrow}>1. KLIENT</Text><View style={s.form2}><Field label="Klient" value={d.name} onChangeText={x=>setD({...d,name:x})}/><Field label="Telefon" value={d.phone} onChangeText={x=>setD({...d,phone:x})}/><Field label="Rejestracja" value={d.plate} onChangeText={x=>setD({...d,plate:x})}/><View style={{flex:1,minWidth:210}}><Field label="VIN" value={d.vin} onChangeText={x=>setD({...d,vin:x})}/><Button small onPress={()=>setScan(true)}>▣ Skanuj VIN / AZTEC</Button></View></View><Text style={[s.eyebrow,{marginTop:18}]}>2. POJAZD</Text><View style={s.form2}>{manual.make?<Field label="Marka" value={d.make} onChangeText={x=>setD({...d,make:x})}/>:<SelectField label="Marka" value={d.make} items={vehicleMakes} onChange={x=>choose('make',x)}/>}{manual.model?<Field label="Model" value={d.model} onChangeText={x=>setD({...d,model:x})} disabled={!d.make}/>:<SelectField label="Model" value={d.model} items={models} onChange={x=>choose('model',x)} disabled={!d.make}/>}{manual.generation||(!hasDetails&&!!d.model)?<Field label="Generacja" value={d.generation} onChangeText={x=>setD({...d,generation:x})} placeholder="np. B8 / 8K / F30" disabled={!d.model}/>:<SelectField label="Generacja" value={d.generation} items={generations} onChange={x=>choose('generation',x)} disabled={!d.model}/>}{manual.year?<Field label="Rok" value={d.year} onChangeText={x=>setD({...d,year:x})} keyboardType="numeric"/>:<SelectField label="Rok" value={d.year} items={years} onChange={x=>choose('year',x)} disabled={!d.model||(hasDetails&&!d.generation)} manualLabel="Inny rok…"/>}{manual.engine||!engines.length?<Field label="Silnik" value={d.engine} onChangeText={x=>setD({...d,engine:x})} placeholder="np. 2.0 TDI" disabled={!d.model}/>:<SelectField label="Silnik" value={d.engine} items={engines} onChange={x=>choose('engine',x)} disabled={!d.model||(hasDetails&&!d.generation)}/>}{manual.power||!powers.length?<Field label="Moc [KM]" value={d.power_hp} onChangeText={x=>setD({...d,power_hp:x})} keyboardType="numeric" disabled={!d.engine}/>:<SelectField label="Moc [KM]" value={d.power_hp} items={powers.map(x=>`${x}`)} onChange={x=>choose('power',x)} disabled={!d.engine} manualLabel="Inna moc…"/>}{manual.code||!codes.length?<Field label="Kod silnika" value={d.engine_code} onChangeText={x=>setD({...d,engine_code:x.toUpperCase()})} placeholder="np. AVQ / BKD" disabled={!d.engine}/>:<SelectField label="Kod silnika" value={d.engine_code} items={codes} onChange={x=>choose('code',x)} disabled={!d.engine} manualLabel="Inny kod…"/>}<Field label="Przebieg" value={d.mileage} onChangeText={x=>setD({...d,mileage:x})} keyboardType="numeric"/></View><Text style={[s.eyebrow,{marginTop:18}]}>3. ZLECENIE</Text><Field label="Temat zlecenia" value={d.title} onChangeText={x=>setD({...d,title:x})}/><Field label="Opis klienta / objawy" value={d.complaint} onChangeText={x=>setD({...d,complaint:x})} multiline voice/><Field label="Notatka przyjęcia" value={d.intake_notes} onChangeText={x=>setD({...d,intake_notes:x})} multiline voice/><Button primary onPress={save}>Zapisz przyjęcie</Button><VinScanner visible={scan} onClose={()=>setScan(false)} onData={result=>{const f=canonicalVehicleForm(result.form||{}),knownMake=vehicleMakes.includes(f.make),knownModel=knownMake&&vehicleModels(f.make).includes(f.model);setD({...d,...f,name:f.customer_name||d.name});setManual({make:Boolean(f.make&&!knownMake),model:Boolean(f.model&&!knownModel),generation:false,year:Boolean(f.year),engine:Boolean(f.engine),power:Boolean(f.power_hp),code:false});setScan(false)}}/></Section>
}
