function MobileVehicleHealth({health}){const tone=health.tone==='critical'?'#e26b5d':health.tone==='warn'?'#e0b44a':health.tone==='unknown'?'#819086':'#a7db68';return <View style={vh.card}><View style={vh.head}><View style={[vh.score,{borderColor:tone,shadowColor:tone}]}><Text style={vh.scoreValue}>{health.displayScore==null?'—':health.displayScore}</Text><Text style={vh.scoreUnit}>{health.displayScore==null?'BRAK DANYCH':'/ 100'}</Text></View><View style={{flex:1}}><Text style={[s.eyebrow,{color:tone}]}>VEHICLE HEALTH SCORE</Text><Text style={vh.state}>{health.state}</Text><Text style={s.muted}>{health.issueCount?`${health.issueCount} zapisanych czynników wpływa na ocenę.`:'Brak zapisanych otwartych usterek lub zaległych obsług.'}</Text><Text style={vh.coverage}>KOMPLETNOŚĆ DANYCH · {health.coverage}%</Text></View></View><View style={vh.systems}>{health.subsystems.map(system=><View key={system.id} style={vh.system}><View style={vh.systemHead}><Text style={vh.systemName}>{system.label}</Text><Text style={vh.systemValue}>{system.score}</Text></View><View style={vh.bar}><View style={[vh.barFill,{width:`${system.score}%`,backgroundColor:system.tone==='critical'?'#e26b5d':system.tone==='warn'?'#e0b44a':'#9fd164'}]}/></View><Text style={vh.systemNote} numberOfLines={1}>{system.issues[0]?.title||'brak zapisanych uwag'}</Text></View>)}</View>{health.actions.length>0&&<View style={vh.actions}><Text style={s.eyebrow}>NASTĘPNE DZIAŁANIA</Text>{health.actions.map((action,index)=><View key={`${action.system}-${index}`} style={vh.action}><Text style={vh.actionNo}>{index+1}</Text><Text style={vh.actionText}>{action.title}</Text></View>)}</View>}<Text style={vh.foot}>Wynik powstaje wyłącznie z zapisów warsztatu i nie zastępuje pomiarów.</Text></View>}
